sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float phase;
uniform float angle;
uniform float spacing;
uniform float magnitude;
uniform float warpAngle;
uniform float speed;

half4 main(float2 coord) {
    float a = radians(angle);
    float b = radians(warpAngle);
    float u = dot(coord / max(size, float2(1.0)), float2(cos(a), sin(a)));
    float d = magnitude * min(screen.z, screen.w) * 0.01 * sin(spacing * u + 6.2831853 * phase + time * speed);
    return image.eval(coord + d * float2(cos(b), sin(b)));
}
